const source = $('Execute Workflow Trigger').item.json || {};

const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  message.text ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanQuery(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function extractSearchQuery(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'tim file',
    'search file',
    'kiem file',
    'tim trong drive',
    'find file',
    'tim tep',
    'kiem tep',
    'search drive',
    'drive search'
  ];

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      return cleanQuery(original.slice(prefix.length + 1));
    }

    if (normalized === prefix) {
      return '';
    }
  }

  return '';
}

const query = cleanQuery(
  source.query ||
  source.fileName ||
  payload.query ||
  payload.fileName ||
  extractSearchQuery(raw)
);

const mimeType =
  source.mimeType ||
  payload.mimeType ||
  '';

const limit = Number(
  source.limit ||
  payload.limit ||
  10
) || 10;

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),
    query,
    fileName: query,
    mimeType,
    limit,
    hasTarget: Boolean(query),
    response: query
      ? ''
      : '📁 <b>Tìm file trong Drive</b>\n\nVí dụ: <code>tìm file hợp đồng</code>',
  },
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const formatDate = (value) => {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? ''
    : date.toLocaleString('vi-VN', {
        timeZone: 'Asia/Ho_Chi_Minh',
        hour12: false,
      });
};

const getFileType = (mimeType = '') => {
  if (mimeType === 'application/vnd.google-apps.folder') {
    return { icon: '📁', label: 'Folder' };
  }

  if (mimeType === 'application/vnd.google-apps.document') {
    return { icon: '📝', label: 'Google Docs' };
  }

  if (mimeType === 'application/vnd.google-apps.spreadsheet') {
    return { icon: '📊', label: 'Google Sheets' };
  }

  if (mimeType === 'application/vnd.google-apps.presentation') {
    return { icon: '📽️', label: 'Google Slides' };
  }

  if (mimeType === 'application/pdf') {
    return { icon: '📕', label: 'PDF' };
  }

  if (mimeType.includes('wordprocessingml') || mimeType === 'application/msword') {
    return { icon: '📄', label: 'Word' };
  }

  if (mimeType.includes('spreadsheetml') || mimeType === 'application/vnd.ms-excel') {
    return { icon: '📊', label: 'Excel' };
  }

  if (mimeType.includes('presentationml') || mimeType === 'application/vnd.ms-powerpoint') {
    return { icon: '📽️', label: 'PowerPoint' };
  }

  if (mimeType.startsWith('image/')) {
    return { icon: '🖼️', label: 'Image' };
  }

  if (mimeType.startsWith('video/')) {
    return { icon: '🎬', label: 'Video' };
  }

  if (mimeType.startsWith('audio/')) {
    return { icon: '🎵', label: 'Audio' };
  }

  if (
    mimeType === 'application/zip' ||
    mimeType === 'application/x-zip-compressed' ||
    mimeType.includes('compressed')
  ) {
    return { icon: '🗜️', label: 'Archive' };
  }

  if (mimeType.startsWith('text/')) {
    return { icon: '📄', label: 'Text' };
  }

  return { icon: '📄', label: 'File' };
};

const shortenId = (id = '') => {
  const value = String(id || '');
  if (value.length <= 16) return value;
  return `${value.slice(0, 8)}...${value.slice(-6)}`;
};

const source = $('Prepare Action').item.json;

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name)
  .sort((a, b) => {
    const timeA = new Date(a.modifiedTime || a.createdTime || 0).getTime();
    const timeB = new Date(b.modifiedTime || b.createdTime || 0).getTime();
    return timeB - timeA;
  });

const query = pickFirst(source.query, source.fileName, source.rawText, source.text);

let text = '🔎 <b>Kết quả tìm file trong Google Drive</b>\n\n';

if (query) {
  text += `Từ khóa: <i>${escapeHtml(query)}</i>\n\n`;
}

if (!rows.length) {
  text += query
    ? `Không tìm thấy file phù hợp với: <i>${escapeHtml(query)}</i>`
    : 'Không tìm thấy file phù hợp.';
} else {
  rows.forEach((file, index) => {
    const name = file.name || 'Không rõ tên';
    const link = pickFirst(file.webViewLink);
    const modified = formatDate(file.modifiedTime);
    const created = formatDate(file.createdTime);
    const fileType = getFileType(file.mimeType || '');
    const fileId = pickFirst(file.id, file.fileId);

    text += `${index + 1}. ${fileType.icon} `;

    if (link) {
      text += `<a href="${escapeHtml(link)}">${escapeHtml(name)}</a>\n`;
    } else {
      text += `<b>${escapeHtml(name)}</b>\n`;
    }

    text += `   Loại: ${escapeHtml(fileType.label)}\n`;

    if (modified) {
      text += `   Sửa lúc: ${escapeHtml(modified)}\n`;
    } else if (created) {
      text += `   Tạo lúc: ${escapeHtml(created)}\n`;
    }

    if (fileId) {
      text += `   ID: <code>${escapeHtml(shortenId(fileId))}</code>\n`;
    }

    text += '\n';
  });

}

return [{
  json: {
    chatId: source.chatId,
    text: text.trim(),
  },
}];
